func satSubUint16SVE2Guarded(dst []uint16, a []uint16, b []uint16) {
	n := min(len(dst), len(a), len(b))
	if n < 16 {
		ref.SatSub(dst, a, b)
		return
	}
	satSubUint16SVE2(dst[:n:n], a, b)
}

